/* WSPR encoder checks: known-good symbol vector + synthesis sanity. */
#include "dsp/wspr.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>

/* K1ABC FN42 37 dBm, generated by Etherkit JTEncode (independent reference). */
static const uint8_t k_ref[162] = {
    3,3,0,0,2,0,0,0,1,0,2,0,1,3,1,2,2,2,1,0,0,3,2,3,1,3,3,2,2,0,2,0,0,0,3,2,0,1,2,3,
    2,2,0,0,2,2,3,2,1,1,0,2,3,3,2,1,0,2,2,1,3,2,1,2,2,2,0,3,3,0,3,0,3,0,1,2,1,0,2,1,
    2,0,3,2,1,3,2,0,0,3,3,2,3,0,3,2,2,0,3,0,2,0,2,0,1,0,2,3,0,2,1,1,1,2,3,3,0,2,3,1,
    2,1,2,2,2,1,3,3,2,0,0,0,0,1,0,3,2,0,1,3,2,2,2,2,2,0,2,3,3,2,3,2,3,3,2,0,0,3,1,2,
    2,2
};

int main(void)
{
    uint8_t s[162];
    int fail = 0;
    if (wspr_encode("K1ABC", "FN42", 37, s)) { printf("encode failed\n"); return 1; }
    int diff = 0;
    for (int i = 0; i < 162; ++i) diff += s[i] != k_ref[i];
    printf("K1ABC FN42 37: %s\n", diff ? "MISMATCH vs reference" : "matches reference vector");
    fail |= diff != 0;
    printf("power snapping: 5->%d 25->%d 36->%d\n", wspr_valid_dbm(5), wspr_valid_dbm(25), wspr_valid_dbm(36));
    printf("reject N0CALL (4-letter suffix): %s\n", wspr_encode("N0CALL", "FN42", 23, s) ? "rejected" : "ACCEPTED");
    printf("1-letter prefix K1JT -> ' K1JT  ': %s\n", wspr_encode("K1JT", "FN20", 30, s) ? "FAIL" : "ok");
    float *w = malloc(sizeof(float) * 162 * 8192);
    size_t n = wspr_synth(s, 1500, 12000, 0.5f, w);
    printf("synth: %zu samples = %.2f s\n", n, n / 12000.0);
    fail |= fabs(n / 12000.0 - 110.59) > 0.05;
    free(w);
    printf(fail ? "FAIL\n" : "PASS\n");
    return fail;
}
